create table marketing.campaigns (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, status text not null default 'draft', starts_at timestamptz, ends_at timestamptz, budget numeric(18,2), currency text, created_at timestamptz not null default now());
create table marketing.attribution_events (id uuid primary key default gen_random_uuid(), customer_id uuid references customer.customers(id), session_key text, event_type text not null, source text, medium text, campaign text, content text, landing_page text, occurred_at timestamptz not null default now(), payload jsonb not null default '{}');
create table marketing.experiments (id uuid primary key default gen_random_uuid(), experiment_key text unique not null, name text not null, status text not null default 'draft', metric_definition jsonb not null default '{}', created_at timestamptz not null default now());
create table marketing.experiment_variants (id uuid primary key default gen_random_uuid(), experiment_id uuid not null references marketing.experiments(id) on delete cascade, variant_key text not null, config_json jsonb not null default '{}', unique(experiment_id,variant_key));
create table customer.wishlists (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customer.customers(id) on delete cascade, name text not null default 'Default', created_at timestamptz not null default now());
create table customer.wishlist_items (wishlist_id uuid not null references customer.wishlists(id) on delete cascade, product_variant_id uuid not null references catalog.product_variants(id), added_at timestamptz not null default now(), primary key(wishlist_id,product_variant_id));
create table customer.point_accounts (id uuid primary key default gen_random_uuid(), customer_id uuid unique not null references customer.customers(id) on delete cascade, balance numeric(18,3) not null default 0 check(balance>=0), updated_at timestamptz not null default now());
create table customer.point_transactions (id uuid primary key default gen_random_uuid(), point_account_id uuid not null references customer.point_accounts(id), transaction_type text not null, points numeric(18,3) not null, reference_type text, reference_id uuid, created_at timestamptz not null default now());
create table catalog.bundles (id uuid primary key default gen_random_uuid(), code text unique not null, name_ar text not null, name_en text, status text not null default 'draft', pricing_rule jsonb not null default '{}', created_at timestamptz not null default now());
create table catalog.bundle_items (bundle_id uuid not null references catalog.bundles(id) on delete cascade, product_variant_id uuid not null references catalog.product_variants(id), quantity numeric(18,3) not null check(quantity>0), primary key(bundle_id,product_variant_id));
create table finance.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references commerce.orders(id), provider_code text, provider_reference text, status text not null default 'pending', amount numeric(18,2) not null, currency text not null, paid_at timestamptz, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table finance.financial_transactions (id uuid primary key default gen_random_uuid(), transaction_type text not null, order_id uuid references commerce.orders(id), payment_id uuid references finance.payments(id), amount numeric(18,2) not null, currency text not null, description text, reference_type text, reference_id uuid, created_at timestamptz not null default now());
create table finance.settlements (id uuid primary key default gen_random_uuid(), provider_code text, settlement_reference text, settlement_date date, gross_amount numeric(18,2), fees numeric(18,2), net_amount numeric(18,2), currency text, status text not null default 'pending', payload jsonb not null default '{}', created_at timestamptz not null default now());
create table finance.reconciliations (id uuid primary key default gen_random_uuid(), settlement_id uuid references finance.settlements(id), status text not null default 'open', matched_amount numeric(18,2) default 0, notes text, created_at timestamptz not null default now());
create table ai.recommendations (id uuid primary key default gen_random_uuid(), type text not null, title text not null, evidence jsonb not null default '{}', confidence numeric(6,5), status text not null default 'new', created_at timestamptz not null default now());
create table ai.action_requests (id uuid primary key default gen_random_uuid(), action_type text not null, target_type text, target_id uuid, proposed_payload jsonb not null default '{}', risk_level text not null default 'medium', status text not null default 'pending_approval', requested_by uuid references identity.user_profiles(id), approved_by uuid references identity.user_profiles(id), approved_at timestamptz, execution_id uuid, created_at timestamptz not null default now());
alter table marketing.campaigns enable row level security; alter table marketing.attribution_events enable row level security; alter table marketing.experiments enable row level security; alter table marketing.experiment_variants enable row level security; alter table customer.wishlists enable row level security; alter table customer.wishlist_items enable row level security; alter table customer.point_accounts enable row level security; alter table customer.point_transactions enable row level security; alter table catalog.bundles enable row level security; alter table catalog.bundle_items enable row level security; alter table finance.payments enable row level security; alter table finance.financial_transactions enable row level security; alter table finance.settlements enable row level security; alter table finance.reconciliations enable row level security; alter table ai.recommendations enable row level security; alter table ai.action_requests enable row level security;
create policy wishlist_owner on customer.wishlists for all to authenticated using(customer_id in(select id from customer.customers where auth_user_id=auth.uid())) with check(customer_id in(select id from customer.customers where auth_user_id=auth.uid()));
create policy wishlist_items_owner on customer.wishlist_items for all to authenticated using(wishlist_id in(select id from customer.wishlists where customer_id in(select id from customer.customers where auth_user_id=auth.uid()))) with check(wishlist_id in(select id from customer.wishlists where customer_id in(select id from customer.customers where auth_user_id=auth.uid())));
create policy marketing_staff on marketing.campaigns for all to authenticated using(platform.has_permission(auth.uid(),'marketing.manage')) with check(platform.has_permission(auth.uid(),'marketing.manage'));
create policy finance_staff on finance.payments for select to authenticated using(platform.has_permission(auth.uid(),'finance.read') or order_id in(select id from commerce.orders where customer_id in(select id from customer.customers where auth_user_id=auth.uid())));
create policy ai_read on ai.recommendations for select to authenticated using(platform.has_permission(auth.uid(),'ai.read'));
create policy ai_approval on ai.action_requests for update to authenticated using(platform.has_permission(auth.uid(),'ai.approve')) with check(platform.has_permission(auth.uid(),'ai.approve'));
create index idx_attribution_customer on marketing.attribution_events(customer_id,occurred_at desc); create index idx_campaign_status on marketing.campaigns(status,starts_at); create index idx_wishlist_customer on customer.wishlists(customer_id); create index idx_points_account on customer.point_transactions(point_account_id,created_at desc); create index idx_payments_order on finance.payments(order_id,created_at desc); create index idx_financial_order on finance.financial_transactions(order_id,created_at desc); create index idx_ai_actions_status on ai.action_requests(status,created_at desc);